-- Especificación (no ejecutar desde BA). Objeto: SPQ_FTR_AUT_DISP_COL (modelo FTR_AUT_DISP_COL).
-- Fuente patrón: sql_refe/0100016283/SPQ_FTR_MASIVA_COL.sql · FACTURAR_MASI (~L406-415).
-- Aplicar al inicio de METODO IN ('FACTURA_AUT_NOPBS','FACTURAR_MASI_PBS') tras parsear @PARAMETROS:

DECLARE @IDSEDE_FILTRO VARCHAR(20);
SELECT @IDSEDE_FILTRO = IDSEDE FROM OPENJSON(@PARAMETROS) WITH (IDSEDE VARCHAR(20) '$.IDSEDE');

IF UPPER(LTRIM(RTRIM(COALESCE(@IDSEDE_FILTRO,'')))) IN ('TODAS','TODA','')
   OR @IDSEDE_FILTRO = 'Todas'
BEGIN
   INSERT INTO @TBLERRORES(ERROR)
   SELECT 'Debe seleccionar una sede concreta para facturar. Todas solo sirve para consultar autorizaciones.';
   SELECT 'KO' OK;
   SELECT ERROR FROM @TBLERRORES;
   RETURN;
END

IF dbo.FNK_VALORVARIABLE('FACTSEDE')='SI' AND @IDSEDE_FILTRO = 'Todas'
BEGIN
   INSERT INTO @TBLERRORES(ERROR)
   SELECT 'Escogio Todas las Sedes y esta IPS Tiene configurado Facturación por Sede';
   SELECT 'KO' OK;
   SELECT ERROR FROM @TBLERRORES;
   RETURN;
END

